package info.java;

import java.util.HashSet;

public class HashSetCount {
    public static void main(String[] args) {

        HashSet<String> set = new HashSet<>();

        set.add("Apple");
        set.add("Banana");
        set.add("Mango");
        set.add("Orange");
        set.add("Grapes");

        System.out.println("HashSet: " + set);

        System.out.println("Number of elements: " + set.size());
    }
}




	
